{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summary の hs",
      "detail": "stdにある「各団体の説明に基づいて紹介する」という主要な内容が抜けており、全体のまとめとして情報が不足しています。",
      "fix": "日本でファクトチェックを行う主な非営利団体を、それぞれの説明をもとに紹介します。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/2/text の hs",
      "detail": "stdにある「ガイドラインの公開、疑義言説のモニタリングと情報提供、結果を検索できるFactCheck Navi（2019年以降）の運営を行う」という具体的な活動内容がすべて抜け落ちており、内容が大きく変わっています。",
      "fix": "FIJは自分でチェックをせず、ルールを公開したり、あやしい話を見張ったり、「FactCheck Navi」という検索サイトを運営したりしています。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/3/text の hs",
      "detail": "stdにある「運営委員会が非党派性と公正性を評価するとしている」という情報が抜け落ちています。",
      "fix": "日本ファクトチェックセンターはネットの会社を中心につくる団体の中にあり、チェックは編集部にまかせられ、運営委員会がかたよっていないか評価します。"
    },
    {
      "type": "評価・意見",
      "where": "blocks/5/text の hs",
      "detail": "stdにはない「その出典も自分で開いて見てみましょう」という読者への行動を促すアドバイス（意見）が追加されています。",
      "fix": "その出典を自分で確認できます。"
    }
  ]
}
